import React, { useState, useEffect } from "react";

export default function CodeExplainer() {
  const [room, setRoom] = useState("0I6PXI");
  const [code, setCode] = useState("");
  const [comment, setComment] = useState("");
  const [comments, setComments] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [explanation, setExplanation] = useState("");

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const roomCode = urlParams.get('room');
    if (roomCode) setRoom(roomCode);
  }, []);

  const handleExplain = async () => {
    if (!code.trim()) {
      alert("Please paste your code first!");
      return;
    }
    
    setIsLoading(true);
    setTimeout(() => {
      const lines = code.split('\n').length;
      const chars = code.length;
      const funcs = code.match(/function|=>/g)?.length || 0;
      const vars = code.match(/\b(let|const|var)\s+/g)?.length || 0;
      
      setExplanation(`## Code Analysis

**Overview:**
Your code contains ${lines} lines and ${chars} characters.

**Structure:**
• Functions/Arrow Functions: ${funcs}
• Variables Declared: ${vars}
• Estimated Complexity: ${lines > 50 ? 'High' : lines > 20 ? 'Medium' : 'Low'}

**Quality Insights:**
✓ Code structure looks clean
✓ Consider adding comments for complex logic
✓ Use meaningful variable names

**Suggestions:**
→ Add error handling with try-catch blocks
→ Consider breaking down large functions
→ Use modern ES6+ features where possible
→ Add input validation

**Performance Tips:**
⚡ Optimize loops and reduce nested iterations
⚡ Use async/await for better async handling
⚡ Consider memoization for expensive operations`);
      setIsLoading(false);
    }, 1800);
  };

  const handleSendComment = () => {
    if (!comment.trim()) return;
    setComments([...comments, {
      id: Date.now(),
      text: comment,
      user: "You",
      timestamp: new Date().toLocaleTimeString()
    }]);
    setComment("");
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
        padding: "25px",
        fontFamily: "'Inter', -apple-system, sans-serif",
      }}
    >
      <div
        style={{
          maxWidth: "1500px",
          margin: "0 auto",
        }}
      >
        {/* Header */}
        <div
          style={{
            background: "rgba(0,0,0,0.3)",
            backdropFilter: "blur(10px)",
            borderRadius: "16px 16px 0 0",
            padding: "20px 30px",
            border: "1px solid rgba(255,255,255,0.15)",
            borderBottom: "none",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <div>
            <h1 style={{ fontSize: "26px", fontWeight: 700, color: "#fff", margin: 0, marginBottom: "5px" }}>
              🤖 Code Explainer
            </h1>
            <p style={{ color: "rgba(255,255,255,0.7)", fontSize: "14px", margin: 0 }}>
              Room: <span style={{ color: "#fff", fontWeight: 600, fontFamily: "monospace" }}>{room}</span>
              <span style={{ margin: "0 10px", color: "rgba(255,255,255,0.4)" }}>•</span>
              <span style={{ fontSize: "13px" }}>Powered by Gemini + FastAPI</span>
            </p>
          </div>
          <button
            onClick={() => alert('Navigate back to lobby')}
            style={{
              padding: "10px 20px",
              background: "rgba(255,255,255,0.15)",
              border: "1px solid rgba(255,255,255,0.2)",
              borderRadius: "8px",
              color: "#fff",
              fontSize: "14px",
              fontWeight: 600,
              cursor: "pointer",
              transition: "all 0.2s ease",
            }}
            onMouseOver={(e) => e.target.style.background = "rgba(255,255,255,0.25)"}
            onMouseOut={(e) => e.target.style.background = "rgba(255,255,255,0.15)"}
          >
            ← Back
          </button>
        </div>

        {/* Main Content */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "70% 30%",
            gap: "0",
            background: "#16161f",
            border: "1px solid rgba(255,255,255,0.15)",
          }}
        >
          {/* Left - Code Editor */}
          <div style={{ borderRight: "1px solid rgba(255,255,255,0.1)", display: "flex", flexDirection: "column" }}>
            {/* Code Editor Header */}
            <div
              style={{
                padding: "15px 25px",
                background: "#1f1f2e",
                borderBottom: "1px solid rgba(255,255,255,0.1)",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <h3 style={{ color: "#fff", fontSize: "15px", margin: 0, fontWeight: 600 }}>
                📝 Code Editor
              </h3>
              <span style={{ color: "rgba(255,255,255,0.4)", fontSize: "12px" }}>
                {code.split('\n').length} lines • {code.length} chars
              </span>
            </div>

            <textarea
              value={code}
              onChange={(e) => setCode(e.target.value)}
              placeholder="Type your code here..."
              style={{
                width: "100%",
                height: "450px",
                background: "#0d0d12",
                border: "none",
                padding: "25px",
                color: "#e8e8e8",
                fontSize: "14px",
                fontFamily: "'Fira Code', 'Courier New', monospace",
                resize: "none",
                outline: "none",
                lineHeight: "1.7",
              }}
            />

            {/* Explanation Box */}
            {explanation && (
              <div
                style={{
                  padding: "25px",
                  background: "#0d0d12",
                  borderTop: "1px solid rgba(255,255,255,0.1)",
                  maxHeight: "350px",
                  overflowY: "auto",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "20px" }}>
                  <span style={{ fontSize: "24px" }}>✨</span>
                  <h3 style={{ color: "#667eea", fontSize: "17px", margin: 0, fontWeight: 700 }}>
                    AI Explanation
                  </h3>
                </div>
                <div style={{ color: "#d0d0d0", fontSize: "14px", lineHeight: "1.8" }}>
                  {explanation.split('\n\n').map((section, idx) => {
                    const lines = section.split('\n');
                    const title = lines[0];
                    const content = lines.slice(1);
                    
                    return (
                      <div key={idx} style={{ marginBottom: "20px" }}>
                        {title.startsWith('**') ? (
                          <h4 style={{ 
                            fontSize: "15px", 
                            color: "#8b8bff", 
                            marginBottom: "10px", 
                            fontWeight: 600 
                          }}>
                            {title.replace(/\*\*/g, '')}
                          </h4>
                        ) : (
                          <h4 style={{ 
                            fontSize: "16px", 
                            color: "#fff", 
                            marginBottom: "12px", 
                            fontWeight: 600 
                          }}>
                            {title.replace('## ', '')}
                          </h4>
                        )}
                        {content.map((line, lineIdx) => (
                          <div key={lineIdx} style={{ 
                            paddingLeft: line.startsWith('•') || line.startsWith('✓') || line.startsWith('→') || line.startsWith('⚡') ? "5px" : "0",
                            marginBottom: "6px",
                            color: "#c0c0c0"
                          }}>
                            {line}
                          </div>
                        ))}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>

          {/* Right - Comments */}
          <div style={{ display: "flex", flexDirection: "column" }}>
            <div
              style={{
                padding: "15px 20px",
                borderBottom: "1px solid rgba(255,255,255,0.1)",
                background: "#1f1f2e",
              }}
            >
              <h3 style={{ color: "#fff", fontSize: "15px", margin: 0, fontWeight: 600 }}>💬 Comments</h3>
            </div>

            <div
              style={{
                flex: 1,
                padding: "20px",
                overflowY: "auto",
                background: "#0d0d12",
              }}
            >
              {comments.length === 0 ? (
                <div style={{ textAlign: "center", paddingTop: "60px" }}>
                  <div style={{ fontSize: "48px", marginBottom: "12px", opacity: 0.3 }}>💬</div>
                  <p style={{ color: "#666", fontSize: "14px" }}>No comments yet</p>
                  <p style={{ color: "#555", fontSize: "12px" }}>Start the conversation!</p>
                </div>
              ) : (
                comments.map((c) => (
                  <div
                    key={c.id}
                    style={{
                      background: "rgba(255,255,255,0.04)",
                      borderRadius: "10px",
                      padding: "12px 14px",
                      marginBottom: "10px",
                      border: "1px solid rgba(255,255,255,0.06)",
                    }}
                  >
                    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "6px" }}>
                      <span style={{ color: "#667eea", fontSize: "13px", fontWeight: 600 }}>{c.user}</span>
                      <span style={{ color: "rgba(255,255,255,0.3)", fontSize: "11px" }}>{c.timestamp}</span>
                    </div>
                    <p style={{ color: "#d0d0d0", fontSize: "13px", margin: 0, lineHeight: "1.5" }}>{c.text}</p>
                  </div>
                ))
              )}
            </div>

            <div
              style={{
                padding: "15px",
                background: "#1f1f2e",
                borderTop: "1px solid rgba(255,255,255,0.1)",
              }}
            >
              <input
                type="text"
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSendComment()}
                placeholder="Write a comment..."
                style={{
                  width: "100%",
                  padding: "11px 14px",
                  background: "#0d0d12",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: "8px",
                  color: "#e0e0e0",
                  fontSize: "13px",
                  outline: "none",
                  marginBottom: "8px",
                }}
              />
              <button
                onClick={handleSendComment}
                style={{
                  width: "100%",
                  padding: "11px",
                  background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                  border: "none",
                  borderRadius: "8px",
                  color: "#fff",
                  fontSize: "14px",
                  fontWeight: 600,
                  cursor: "pointer",
                  transition: "transform 0.2s ease",
                }}
                onMouseOver={(e) => e.target.style.transform = "translateY(-1px)"}
                onMouseOut={(e) => e.target.style.transform = "translateY(0)"}
              >
                Send
              </button>
            </div>
          </div>
        </div>

        {/* Bottom Bar */}
        <div
          style={{
            background: "rgba(0,0,0,0.3)",
            backdropFilter: "blur(10px)",
            borderRadius: "0 0 16px 16px",
            padding: "18px 30px",
            border: "1px solid rgba(255,255,255,0.15)",
            borderTop: "none",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <div style={{ display: "flex", gap: "12px", alignItems: "center" }}>
            <button
              onClick={handleExplain}
              disabled={isLoading}
              style={{
                padding: "13px 45px",
                background: isLoading ? "rgba(255,255,255,0.1)" : "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                border: "none",
                borderRadius: "10px",
                color: "#fff",
                fontSize: "15px",
                fontWeight: 700,
                cursor: isLoading ? "not-allowed" : "pointer",
                transition: "all 0.2s ease",
                boxShadow: isLoading ? "none" : "0 4px 15px rgba(102,126,234,0.3)",
              }}
              onMouseOver={(e) => !isLoading && (e.target.style.transform = "translateY(-2px)")}
              onMouseOut={(e) => !isLoading && (e.target.style.transform = "translateY(0)")}
            >
              {isLoading ? "🔄 Analyzing..." : "✨ Explain Code"}
            </button>
            <span style={{ color: "rgba(255,255,255,0.5)", fontSize: "13px" }}>
              Click to analyze your code with AI
            </span>
          </div>
          <p style={{ color: "#888", fontSize: "12px", margin: 0 }}>
            Joined room: <span style={{ color: "#667eea", fontWeight: 600 }}>{room}</span>
          </p>
        </div>
      </div>
    </div>
  );
}
